        oddCount,
        evenPercentage: evenCount / totalTicks * 100,
        oddPercentage: oddCount / totalTicks * 100,
        highPercentage: highCount / totalTicks * 100,
        lowPercentage: lowCount / totalTicks * 100,
        highCount,
        lowCount,
